fn decode_fp_mov16(bits: u32, state: ItState) -> Result<Instruction, DecodeError> {
    if bits & 0xffe00f10 != 0xee000910 {
        return Err(DecodeError::Unallocated);
    }
    // 11101110000|op=x|Vn=xxxx|Rt=xxxx|1001|N=x|xx1xxxx
    let Rt: u8 = ((bits >> 12) & 0xf) as u8;
    let Vn: u8 = ((bits >> 16) & 0xf) as u8;
    let N: u8 = ((bits >> 7) & 0x1) as u8;
    let unpredictable: bool = bits & 0x6f != 0x0 || state.in_block() || Rt == 15;
    match bits & 0x100000 {
        0 => {
            // VMOV (between general-purpose register and half-precision) — From general-purpose register
            // VMOV{<c>}{<q>}.F16  <Sn>, <Rt>
            Ok(Instruction::VmovTohT1 {
                cond: state.condition(),
                Sn: SReg::new(Vn << 1 | N),
                Rt: GpReg::new(Rt),
                unpredictable,
            })
        }
        0x100000 => {
            // VMOV (between general-purpose register and half-precision) — To general-purpose register
            // VMOV{<c>}{<q>}.F16  <Rt>, <Sn>
            Ok(Instruction::VmovHT1 {
                cond: state.condition(),
                Rt: GpReg::new(Rt),
                Sn: SReg::new(Vn << 1 | N),
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

