            let RdLo: u8 = ((bits >> 12) & 0xf) as u8;
            let RdHi: u8 = ((bits >> 8) & 0xf) as u8;
            let Rn: u8 = ((bits >> 16) & 0xf) as u8;
            let Rm: u8 = (bits & 0xf) as u8;
