fn decode_movw(bits: u32, state: ItState) -> Result<Instruction, DecodeError> {
    if bits & 0xfb708000 != 0xf2400000 {
        return Err(DecodeError::Unallocated);
    }
    // 111|10|i=x|1|0|o1=x|10|0|imm4=xxxx|0|imm3=xxx|Rd=xxxx|imm8=xxxxxxxx
    let Rd: u8 = ((bits >> 8) & 0xf) as u8;
    let i: u8 = ((bits >> 26) & 0x1) as u8;
    let imm4: u8 = ((bits >> 16) & 0xf) as u8;
    let imm3: u8 = ((bits >> 12) & 0x7) as u8;
    let imm8: u8 = (bits & 0xff) as u8;
    let unpredictable: bool = Rd == 15;
    match bits & 0x800000 {
        0 => {
            // MOV, MOVS (immediate)
            // MOVW{<c>}{<q>}  <Rd>, #<imm16>
            Ok(Instruction::T3bMovIT3 {
                cond: state.condition(),
                Rd: GpReg::new(Rd),
                imm16: (imm4 as u16) << 12 | (i as u16) << 11 | (imm3 as u16) << 8 | imm8 as u16,
                unpredictable,
            })
        }
        0x800000 => {
            // MOVT
            // MOVT{<c>}{<q>}  <Rd>, #<imm16>
            Ok(Instruction::MovtT1 {
                cond: state.condition(),
                Rd: GpReg::new(Rd),
                imm16: (imm4 as u16) << 12 | (i as u16) << 11 | (imm3 as u16) << 8 | imm8 as u16,
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_mrs_bank(bits: u32, state: ItState) -> Result<Instruction, DecodeError> {
    if bits & 0xffe0d020 != 0xf3e08020 {
        return Err(DecodeError::Unallocated);
    }
    // 111|10|0|1111|1|R=x|M1=xxxx|1|0x0|Rd=xxxx|xx|1|M=x|xxxx
    // MRS (Banked register)
    // MRS{<c>}{<q>}  <Rd>, <banked_reg>
    let Rd: u8 = ((bits >> 8) & 0xf) as u8;
    let R: u8 = ((bits >> 20) & 0x1) as u8;
    let unpredictable: bool = bits & 0x20cf != 0x0 || Rd == 15;
    let M1: u8 = ((bits >> 16) & 0xf) as u8;
    let M: u8 = ((bits >> 4) & 0x1) as u8;
    Ok(Instruction::MrsBrT1As {
        cond: state.condition(),
        Rd: GpReg::new(Rd),
        banked_reg: {
            if matches!(R << 5 | M << 4 | M1, 0x7 | 0xf | 0x18..=0x1b | 0x20..=0x2d | 0x2f | 0x31 | 0x33 | 0x35 | 0x37..=0x3b | 0x3d | 0x3f)
            {
                return Err(DecodeError::Unpredictable);
            }
            match BankedReg::from_bits(R << 5 | M << 4 | M1) {
                Some(symbol) => symbol,
                None => return Err(DecodeError::Unallocated),
            }
        },
        unpredictable,
    })
}

