    // 111|10|0|1110|0|R=x|Rn=xxxx|1|0x0|mask=xxxx|xx|0|xxxxx
    // MSR (register)
    // MSR{<c>}{<q>}  <spec_reg>, <Rn>
    let Rn: u8 = ((bits >> 16) & 0xf) as u8;
