        // VPUSH{<c>}{<q>}{.<size>}  <sreglist>
        // VSTM, VSTMDB, VSTMIA — Decrement Before
        // VSTMDB{<c>}{<q>}{.<size>}  <Rn>!, <sreglist>
        let d: u8 = Vd << 1 | D;
        let Rn: u8 = ((bits >> 16) & 0xf) as u8;
